serverCode:
string id = parameters["id"].ToString();

result["Fields_Desc"] = tDAL.DBLookup(
    "SELECT Fields_Desc FROM OneForm_Fields WHERE ID = '" + id.Replace("'", "''") + "'"
);

afterJsCode:
var description = result["Fields_Desc"] &&
                  result["Fields_Desc"]["Fields_Desc"]
    ? result["Fields_Desc"]["Fields_Desc"]
    : "بدون شرح";

$("#field_id_info").remove();

$("#value_Field_ID_27").closest(".r-integrated-field").after(
    $("<div>", {
        id: "field_id_info",
        class: "form-group",
        css: {
            "margin-top": "6px",
            "color": "blue",
            "font-weight": "bold",
            "whiteSpace": "pre-line"
        },
        text: description
    })
);
